import { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

const Register = () => {
    const navigate = useNavigate();
    const [formData, setFormData] = useState({
        numElecteur: "",
        numCNI: "",
        nom: "",
        bureauVote: "",
        email: "",
        telephone: "",
        prenom: "",
    });

    const [step, setStep] = useState(1);
    const [errorMessage, setErrorMessage] = useState("");

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setErrorMessage("");  // Réinitialiser le message d'erreur

        try {
            if (step === 1) {
                const res = await axios.post("http://localhost:5000/api/verify-elector", formData);
                if (res.data.valid) {
                    setStep(2);
                } else {
                    setErrorMessage("Informations incorrectes ou électeur introuvable.");
                }
            } else {
                const res = await axios.post("http://localhost:5000/api/register-elector", formData);
                if (res.data.success) {
                    alert("Inscription réussie, code envoyé !");
                    navigate("/login");
                } else {
                    setErrorMessage("Erreur lors de l'inscription.");
                }
            }
        } catch (error) {
            console.error("Erreur backend:", error);
            setErrorMessage(error.response?.data?.error || "Erreur d'inscription.");
        }
    };

    return (
        <div className="register-container">
            <h2>Inscription des électeurs</h2>
            {errorMessage && <p className="error-message">{errorMessage}</p>}
            <form onSubmit={handleSubmit}>
                {step === 1 ? (
                    <>
                        <input type="text" name="numElecteur" placeholder="Numéro d’électeur" onChange={handleChange} required />
                        <input type="text" name="numCNI" placeholder="Numéro CNI" onChange={handleChange} required />
                        <input type="text" name="nom" placeholder="Nom de famille" onChange={handleChange} required />
                        <input type="text" name="bureauVote" placeholder="Numéro de bureau de vote" onChange={handleChange} required />
                    </>
                ) : (
                    <>
                        <input type="text" name="prenom" placeholder="Prénom" onChange={handleChange} required />
                        <input type="email" name="email" placeholder="Adresse email" onChange={handleChange} required />
                        <input type="text" name="telephone" placeholder="Numéro de téléphone" onChange={handleChange} required />
                    </>
                )}
                <button type="submit">{step === 1 ? "Vérifier" : "S'inscrire"}</button>
            </form>
        </div>
    );
};

export default Register;
